import re
MEAT=r'\b(?:kurczak|indyk|kacz|wołowin|wieprzow|schab|boczek|boczku|szynk|kiełbas|chorizo|salami|mięso|mięsn|cielęc|jagnięc|jagnię|baranin|polędwic|żeberk|karkówk|łopatk|stek|pancetta|guanciale|prosciutto|wędlin|gęsi|gęś|królik|wątrob|mortadel|kabanos|parówk|krewetk|łosoś|łososi|dorsz|tuńczyk|śledź|śledz|sardyn|anchois|makrel|pstrąg|\bryb|owoce morza|małż|omułk|kalmar|ośmiorn|\bkrab|homar|sandacz|karp|halibut|mintaj|morszczuk|okoń|szczupak|węgorz|ikra|kawior|rosół|bulion (?:drobiowy|wołowy|mięsny|rybny)|smalec|słonin|sos rybny|worcester|żelatyn|skwark|kości|wołowa|mielon(?:a|e) (?:wołowina|wieprzowina)|mięsem|kaczka|gołąb|salceson|nduja|bekon|\bfilet z|kebab|jakitori|dashi|bonito|surimi|przegrzebk|ostryg|mule|mulami|łososia|sola|flądr|pangasius|krewet)'
ANIMAL_NOT_VEGAN=r'\b(?:miód|miodu|miodem|jajk|jajo|jajka|jaj\b|żółtk|białk|mleko(?! kokos| owsian| migdał| sojow| ryżow| roślin)|mleka(?! kokos| owsian| migdał| sojow)|śmietan|śmietank|masło(?! orzech| z orzech| migdał| kakao| shea| z nerkowc| z migdał)|masła|\bser\b|\bsery\b|\bserek|\bsera\b|parmezan|mozzarell|\bfeta|gorgonzol|ricotta|mascarpone|jogurt(?! kokos| sojow| roślin)|maślank|kefir|twaróg|twarog|cheddar|pecorino|halloumi|kajmak|majonez|lody|lodów|czekolada mleczna|czekolada biała|labneh|ghee|burrata|brie|camembert|gouda|emmental|kimchi|ciasto francuskie|grana padano|\bgrana\b|manchego|ser |sernik|skyr|ayran)'
GLUTEN=r'\b(?:mąk|mąka|makaron|spaghetti|penne|tagliatelle|fusilli|lasagne|rigatoni|farfalle|orecchiette|pappardelle|linguine|bucatini|chleb|bułk|bagiet|panko|bułka tarta|tortill|pita\b|naan|kuskus|couscous|bulgur|kasza (?:jęczmienna|manna|pęczak)|pęczak|jęczmie|płatki owsiane|owsian|sos sojowy|piwo|seitan|kluski|pierogi|ciasto francuskie|ciasto filo|herbatnik|biszkopt|ciastka|grzank|krakers|gnocchi|ramen|udon|soba\b|miso|drożdż|piernik|wafl|granola|musli|pszenn|żytni|orkisz|brioch|ciabatt|focaccia|tosty|tost\b|lazanki|łazanki|zacierk|krupnik|mączn|pumpernikl|simit|paluszki|chrupki|grissini|rurki|spód|ciasto)'
GLUTEN_SAFE=r'(?:piwo imbirowe|wafle ryżowe|wafle z ryżu|mąka (?:ryżowa|kukurydziana|kokosowa|migdałowa|ziemniaczana|z ciecierzycy|gryczana|jaglana|ze słodkich|z tapioki|bezglutenowa|z kaszy)|skrobia|makaron (?:ryżowy|sojowy|bezglutenowy|z ciecierzycy|z soczewicy|szklany|gryczany 100)|chleb bezglutenowy|tamari|płatki owsiane bezglutenowe|miso bezglutenowe|kasza jaglana|kasza gryczana|ciasto bezglutenowe|tortilla kukurydziana|tortille kukurydziane|pasta miso bezgl)'
def classify(r):
    ing=' ; '.join(i['name'].lower() for i in r['ingredients'])
    meat=re.search(MEAT,ing)
    animal=re.search(ANIMAL_NOT_VEGAN,ing)
    g=re.sub(GLUTEN_SAFE,' ',ing)
    gl=re.search(GLUTEN,g)
    return meat,animal,gl
